```java
import java.io.*;
import java.util.regex.*;

public class SecureCommandExample {
    public void executeSystemCommand(String userInput) throws IOException {
        // Fix: Validate the input against a strict allow-list (e.g., only alphanumeric characters)
        // to prevent command injection characters like ;, &, |, or > from being processed.
        if (!userInput.matches("^[a-zA-Z0-9.]+$")) {
            throw new IllegalArgumentException("Invalid input: Only hostnames and IP addresses are allowed.");
        }

        // Fix: Avoid using a shell interpreter ("/bin/sh -c"). 
        // Instead, pass the command and its arguments as a list to Runtime.exec.
        // This treats the input strictly as an argument rather than an executable command part.
        String[] command = {"ping", "-c", "1", userInput};

        Process process = Runtime.getRuntime().exec(command);

        try (BufferedReader reader = new BufferedReader(new InputStreamReader(process.getInputStream()))) {
            String line;
            while ((line = reader.readLine()) != null) {
                System.out.println(line);
            }
        }
    }
}
